mapper.select:
select * from file_object
where deleted = 0
and business_type = #{businessType}
and upload_status = #{uploadStatus}
and access = #{access}
and create_by = #{createBy}
and create_time >= #{beginTime}
and create_time <= #{endTime}
order by create_time desc, object_id desc

mapper.update:
update file_object
bucket = #{bucket}, object_key = #{objectKey}, original_name = #{originalName}, content_length = #{contentLength}, content_type = #{contentType}, checksum = #{checksum}, business_type = #{businessType}, biz_ref_id = #{bizRefId}, access = #{access}, upload_status = #{uploadStatus}, deleted = #{deleted}, update_by = #{updateBy}, update_time = now()
where object_id = #{objectId}

mapper.select:
select * from file_object
where deleted = 0 and upload_status = 'PENDING' and create_time < #{ttlBefore}
order by create_time asc
